let current=null,rows={},loadErrors={},user=null,membership=null,memberships=[],membershipLoadError=false,tab='overview',loading=false,error=null,mgRealtime=null;
async function init(){const s=await sb.auth.getSession();user=s.data?.session?.user||null;if(!user)return;let activeId=null;try{activeId=localStorage.getItem('MNTYActiveMembershipId')}catch{}const r=await sb.from('user_memberships').select('id,tenant_id,business_id,branch_id,role,status').eq('user_id',user.id).eq('status','ACTIVE').limit(50);membershipLoadError=!!r.error;memberships=r.error?[]:(r.data||[]);membership=(memberships.find(x=>x.id===activeId)||memberships[0]||null)}
function scope(){return membership?.tenant_id?membership:null}
function canWrite(){return ['OWNER','BUSINESS_OWNER','ADMIN','MANAGER','SERVICE_PROVIDER'].includes(String(membership?.role||'').toUpperCase())}
async function load(d){loading=true;error=null;render();await init();if(!user){error='AUTH_REQUIRED';loading=false;return render()}rows={};loadErrors={};if(d.key==='MANTIGO'){const [customer,captain,earnings]=await Promise.all([sb.rpc('list_mantigo_customer_rides_backend',{p_user_id:user.id,p_ride_id:null}),sb.rpc('list_mantigo_captain_rides_backend',{p_user_id:user.id}),sb.rpc('get_mantigo_captain_earnings_backend',{p_user_id:user.id})]);const mgLoadErrors=[customer.error,captain.error,earnings.error].filter(Boolean);if(mgLoadErrors.length){error='تعذر تحميل بعض بيانات MantiGO. أعد المحاولة، وإذا استمرت المشكلة راجع حالة الاتصال والصلاحيات.';loading=false;return render()}rows.mantigo_customer_tracking=customer.data||[];rows.mantigo_captain_rides=captain.data||[];rows.mantigo_captain_earnings=earnings.data||null;rows.mantigo_rides=rows.mantigo_customer_tracking.map(x=>x.ride||x);rows.mantigo_bids=rows.mantigo_customer_tracking.flatMap(x=>x.bids||[]);rows.mantigo_financial_ledger=rows.mantigo_customer_tracking.map(x=>x.financial).filter(Boolean);const cp=await sb.from('mantigo_captain_profiles').select('captain_id,status,verification_status,availability_status,vehicle_category,vehicle_model,vehicle_plate,rating,completed_rides,acceptance_rate,cancellation_rate,current_lat,current_lon,last_seen_at').eq('captain_id',user.id).maybeSingle();if(cp.error)loadErrors.mantigo_captain_profile=cp.error;rows.mantigo_captain_profile=cp.data||null;if(!mgRealtime){mgRealtime=sb.channel('manti-go-live').on('postgres_changes',{event:'*',schema:'public',table:'mantigo_rides'},()=>{if(current==='MantiGO والنقل')load(defs[current])}).on('postgres_changes',{event:'*',schema:'public',table:'mantigo_bids'},()=>{if(current==='MantiGO والنقل')load(defs[current])}).on('postgres_changes',{event:'*',schema:'public',table:'notifications'},()=>{if(current==='MantiGO والنقل')load(defs[current])}).subscribe()}loading=false;return render()}for(const t of d.tables){if(BACKEND_ONLY_TABLES.has(t)){rows[t]=[];continue}let q=sb.from(t).select('*').limit(150).order('created_at',{ascending:false});if(['catalog_items','catalog_item_prices'].includes(t)){if(membershipLoadError||!scope()?.tenant_id){rows[t]=[];loadErrors[t]={message:'TENANT_SCOPE_UNAVAILABLE'};continue}q=q.eq('tenant_id',scope().tenant_id)}if(t==='marketing_leads')q=q.eq('requester_user_id',user.id);if(t==='marketing_projects'){if(membershipLoadError||!membership?.business_id){rows[t]=[];loadErrors[t]={message:'BUSINESS_SCOPE_UNAVAILABLE'};continue}q=q.eq('client_business_id',membership.business_id)}if(t==='support_tickets')q=q.eq('requester_id',user.id);const r=await q;if(r.error){rows[t]=[];loadErrors[t]=r.error}else rows[t]=r.data||[]}loading=false;render()}
function shell(d,body){return '<section class="workspace-section"><div class="workspace-head"><div><div class="eyebrow">'+d.key+'</div><h2>'+d.desc+'</h2></div></div>'+body+'</section>'}
function tabs(d){const labels={overview:'نظرة عامة',catalog:'الكتالوج',prices:'الأسعار',live:'السجلات والبيانات',providers:'مقدمو الخدمة',services:'الخدمات',leads:'طلبات التسويق',projects:'المشروعات',plans:'الخطط التسويقية',subscriptions:'الاشتراكات',participants:'المشاركون',commissions:'العمولات',documents:'الوثائق',requirements:'المتطلبات',agreements:'الاتفاقيات',requests:'طلبات الصيانة',support:'الدعم الفني',request:'طلب رحلة',open:'الطلبات المفتوحة',myrides:'رحلاتي',bids:'عروض الكباتن',appointments:'المواعيد'};return '<nav class="action-bar" aria-label="أقسام الوحدة" style="gap:8px;flex-wrap:wrap">'+d.tabs.map(x=>'<button type="button" class="btn '+(tab===x?'btn-primary':'btn-outline')+'" data-op-tab="'+x+'" aria-current="'+(tab===x?'page':'false')+'">'+esc(labels[x]||'عرض البيانات')+'</button>').join('')+'</nav>'}
function table(h,rs){return '<div class="table-wrap"><table><thead><tr>'+h.map(x=>'<th>'+x[0]+'</th>').join('')+'</tr></thead><tbody>'+(rs.length?rs.map(r=>'<tr>'+h.map(x=>'<td>'+esc(typeof x[1]==='function'?x[1](r):r[x[1]])+'</td>').join('')+'</tr>').join(''):'<tr><td colspan="'+h.length+'">لا توجد بيانات فعلية ضمن نطاق الصلاحية.</td></tr>')+'</tbody></table></div>'}
function overview(d){const failed=d.tables.some(t=>loadErrors[t]);return shell(d,tabs(d)+(failed?'<div class="notice" role="alert">بعض الجداول لم يتم تحميلها. الأرقام غير متاحة للبيانات المتأثرة؛ يمكنك إعادة المحاولة.</div><button type="button" class="btn btn-outline" data-op-reload>إعادة تحميل البيانات</button>':'')+'<div class="cards">'+d.tables.map(t=>BACKEND_ONLY_TABLES.has(t)?'<article class="card" role="status"><div class="card-title">'+esc(t)+'</div><div class="metric" style="font-size:18px">عرض آمن عبر مسار خلفي</div><div class="muted">لا يتم قراءة هذا الجدول مباشرة من المتصفح؛ استخدم الواجهة الخلفية المصرح بها.</div></article>':loadErrors[t]?'<article class="card" role="status"><div class="card-title">'+esc(t)+'</div><div class="metric" style="font-size:18px">تعذر التحميل</div><div class="muted">تعذر قراءة البيانات؛ لا يمكن عرض عدد السجلات بأمان.</div></article>':'<article class="card"><div class="card-title">'+esc(t)+'</div><div class="metric">'+(rows[t]||[]).length+'</div><div class="muted">سجلات مرئية حاليًا</div></article>').join('')+'</div>')}
function mantigoStatus(s){return ({OPEN:'مفتوح',OPEN_FOR_BIDS:'يستقبل عروضًا',MATCHING:'جارٍ المطابقة',ACCEPTED:'تم قبول الكابتن',ARRIVED:'الكابتن وصل',STARTED:'بدأت الرحلة',IN_PROGRESS:'الرحلة جارية',COMPLETED:'مكتملة',CANCELLED:'ملغاة',FAILED:'فشلت',SHOW_NO:'لم يتم الحضور',EXPIRED:'منتهية'})[s]||s}
function mantigoRideForm(){return '<div class="mg-request-shell"><div class="mg-request-hero"><div><div class="eyebrow">MantiGO · اطلب خدمة النقل</div><h2 style="margin:6px 0 8px">إلى أين تريد الذهاب؟</h2><p class="muted" style="margin:0;max-width:620px">أدخل نقطة الانطلاق والوجهة، اختر المركبة المناسبة، ثم اقترح السعر. سيصل طلبك إلى الكباتن المتاحين لتقديم عروضهم.</p></div><div class="mg-request-badge">⚡ طلب سريع</div></div><div class="mg-step"><span>1</span><div><strong>مسار الرحلة</strong><small>حدد من أين وإلى أين</small></div></div><div class="mg-route-card"><div class="mg-field"><label for="mgPickup">نقطة الانطلاق</label><div class="mg-input-row"><span class="mg-dot mg-dot-start"></span><input id="mgPickup" class="input" placeholder="مثال: شارع فيصل، الجيزة" autocomplete="street-address"><button type="button" class="mg-location-btn" data-mg-location title="استخدم موقعي الحالي">⌖ موقعي</button></div></div><div class="mg-route-line"></div><div class="mg-field"><label for="mgDestination">الوجهة</label><div class="mg-input-row"><span class="mg-dot mg-dot-end"></span><input id="mgDestination" class="input" placeholder="مثال: ميدان التحرير، القاهرة" autocomplete="street-address"></div></div></div><div class="mg-step"><span>2</span><div><strong>اختيارات الرحلة</strong><small>اختر الأنسب لك</small></div></div><div class="mg-choice-grid"><div><label>نوع المركبة</label><div class="mg-choice-row"><button type="button" class="mg-choice active" data-mg-vehicle="CAR">🚗<b>سيارة</b><small>الأكثر استخدامًا</small></button><button type="button" class="mg-choice" data-mg-vehicle="TAXI">🚕<b>تاكسي</b><small>مشوار سريع</small></button><button type="button" class="mg-choice" data-mg-vehicle="VAN">🚐<b>فان</b><small>مساحة أكبر</small></button><button type="button" class="mg-choice" data-mg-vehicle="MOTORCYCLE">🏍️<b>موتوسيكل</b><small>تنقل سريع</small></button></div><input id="mgVehicle" type="hidden" value="CAR"></div><div><label for="mgType">نوع الرحلة</label><select id="mgType" class="input"><option value="ONE_WAY">ذهاب فقط</option><option value="ROUND_TRIP">ذهاب وعودة</option></select></div></div><div class="mg-step"><span>3</span><div><strong>السعر وبيانات التواصل</strong><small>السعر المقترح يساعدك في الحصول على عروض مناسبة</small></div></div><div class="mg-price-card"><div><label for="mgPrice">السعر المقترح</label><div class="mg-price-input"><input id="mgPrice" class="input" type="number" min="1" step="1" placeholder="مثال: 150"><strong>ج.م</strong></div></div><div class="mg-price-hint">💡 يمكنك مقارنة عروض الكباتن قبل قبول أي عرض.</div></div><details class="mg-more"><summary>بيانات إضافية (اختياري)</summary><div class="grid-2" style="margin-top:12px"><input id="mgPhone" class="input" placeholder="رقم التواصل"><textarea id="mgNote" class="input" placeholder="ملاحظات للرحلة، مثل عدد الركاب أو الأمتعة"></textarea></div></details><div class="mg-request-summary"><div><strong>جاهز لنشر الطلب؟</strong><span>سيتم إنشاء الطلب مرة واحدة فقط حتى مع تكرار الضغط.</span></div><button class="btn btn-primary mg-submit-btn" id="mgCreateRide">نشر طلب الرحلة</button></div></div>'}
async function mgGetCurrentPosition(){if(window.MNTYLocationAdapter?.requestLocation){const p=await window.MNTYLocationAdapter.requestLocation();if(p)return {lat:Number(p.latitude.toFixed(6)),lon:Number(p.longitude.toFixed(6))};}if(!navigator.geolocation)return null;return await new Promise(resolve=>navigator.geolocation.getCurrentPosition(p=>resolve({lat:Number(p.coords.latitude.toFixed(6)),lon:Number(p.coords.longitude.toFixed(6))}),()=>resolve(null),{enableHighAccuracy:true,timeout:8000,maximumAge:30000}))}async function mgCreateRide(){const btn=document.getElementById('mgCreateRide');if(btn?.disabled)return;const pickupEl=document.getElementById('mgPickup');if(!pickupEl?.value.trim())return alert('حدد نقطة الانطلاق أولًا.');const destinationEl=document.getElementById('mgDestination');if(!destinationEl?.value.trim())return alert('حدد الوجهة أولًا.');const priceEl=document.getElementById('mgPrice');const proposedPrice=Number(priceEl?.value)||0;if(proposedPrice<=0)return alert('أدخل سعرًا مقترحًا صحيحًا أكبر من صفر.');const key=(crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random());const pos=pickupEl.dataset.lat?{lat:Number(pickupEl.dataset.lat),lon:Number(pickupEl.dataset.lon)}:null;const phone=(document.getElementById('mgPhone')?.value||'').trim();if(phone&&!/^[0-9+\s()-]{7,20}$/.test(phone))return alert('أدخل رقم تواصل صحيحًا.');const p={p_user_id:user.id,p_customer_name:user.user_metadata?.full_name||user.email?.split('@')[0]||'عميل MantiGO',p_customer_phone:document.getElementById('mgPhone').value.trim(),p_vehicle_category:document.getElementById('mgVehicle').value,p_ride_type:document.getElementById('mgType').value,p_pickup_location:pickupEl.value.trim(),p_destination_location:document.getElementById('mgDestination').value.trim(),p_proposed_price:proposedPrice,p_note:document.getElementById('mgNote').value.trim(),p_idempotency_key:key,p_pickup_lat:pickupEl.dataset.lat?Number(pickupEl.dataset.lat):(pos?.lat??null),p_pickup_lon:pickupEl.dataset.lon?Number(pickupEl.dataset.lon):(pos?.lon??null),p_destination_lat:null,p_destination_lon:null};if(!p.p_pickup_location||!p.p_destination_location||p.p_proposed_price<=0)return alert('أكمل نقطة الانطلاق والوجهة والسعر المقترح.');if(btn){btn.disabled=true;btn.dataset.originalText=btn.textContent;btn.textContent='جاري نشر الطلب…';}const r=await sb.rpc('create_mantigo_ride_backend_v2',p);if(r.error){if(btn){btn.disabled=false;btn.textContent=btn.dataset.originalText||'نشر طلب الرحلة';}return alert('تعذر إنشاء طلب الرحلة بسبب الاتصال أو الصلاحيات. تحقق من البيانات ثم حاول مرة أخرى.');}tab='myrides';await load(defs[current])}
function mantigoOpenRides(){const list=rows.mantigo_open||[];return '<div class="cards">'+(list.length?list.map(r=>'<article class="card"><div class="eyebrow">MantiGO</div><h3>'+esc(r.pickup_location)+' ← '+esc(r.destination_location)+'</h3><div class="muted">'+esc(r.vehicle_category)+' · '+esc(r.ride_type)+' · '+money(r.proposed_price)+'</div><p>'+esc(r.note||'بدون ملاحظات')+'</p><span class="mx-live">'+esc(mantigoStatus(r.status))+'</span><div class="action-bar" style="margin-top:10px"><button class="btn btn-primary" data-mg-bid="'+esc(r.id)+'">تقديم عرض</button></div></article>').join(''):'<div class="empty-state">لا توجد رحلات مفتوحة حاليًا.</div>')+'</div>'}
function mantigoBidForm(rideId){return '<div class="card" data-mg-bid-form="'+esc(rideId)+'" style="margin:10px 0"><h3>عرضك على الرحلة</h3><input id="mgBidRide" type="hidden" value="'+esc(rideId)+'"><div class="grid-2"><input id="mgBidName" class="input" placeholder="اسم الكابتن"><input id="mgBidPhone" class="input" placeholder="الهاتف"><select id="mgBidVehicle" class="input"><option value="CAR">سيارة</option><option value="TAXI">تاكسي</option><option value="VAN">فان</option><option value="MOTORCYCLE">موتوسيكل</option></select><input id="mgBidModel" class="input" placeholder="موديل السيارة"><input id="mgBidPlate" class="input" placeholder="رقم اللوحة"><input id="mgBidPrice" class="input" type="number" min="1" placeholder="السعر"><input id="mgBidEta" class="input" type="number" min="0" placeholder="الوصول خلال كم دقيقة؟"><textarea id="mgBidMessage" class="input" placeholder="رسالة للعميل"></textarea></div><button class="btn btn-primary" id="mgSubmitBid">إرسال العرض</button></div>'}
async function mgSubmitBid(){
 const button=document.getElementById('mgSubmitBid');
 if(!button||button.disabled)return;
 const phone=(document.getElementById('mgBidPhone')?.value||'').trim();
 if(phone&&!/^[0-9+\\s()-]{7,20}$/.test(phone))return alert('أدخل رقم تواصل صحيحًا.');
 const rideId=document.getElementById('mgBidRide')?.value;
 const price=Number(document.getElementById('mgBidPrice')?.value)||0;
 if(!rideId)return alert('تعذر تحديد الرحلة المطلوبة. أغلق النموذج وافتحه من الرحلة مرة أخرى.');
 if(price<=0)return alert('أدخل سعر العرض.');
 const p={p_user_id:user.id,p_ride_id:rideId,p_captain_name:document.getElementById('mgBidName')?.value.trim()||user.user_metadata?.full_name||'كابتن MantiGO',p_captain_phone:phone,p_captain_rating:null,p_vehicle_category:document.getElementById('mgBidVehicle')?.value,p_vehicle_model:document.getElementById('mgBidModel')?.value.trim()||'',p_vehicle_plate:document.getElementById('mgBidPlate')?.value.trim()||'',p_offered_price:price,p_eta_minutes:Number(document.getElementById('mgBidEta')?.value)||0,p_captain_message:document.getElementById('mgBidMessage')?.value.trim()||''};
 const originalText=button.textContent;
 button.disabled=true;button.textContent='جاري إرسال العرض…';
 try{
  const r=await sb.rpc('create_mantigo_bid_backend',p);
  if(r.error){alert('تعذر إرسال العرض بسبب الاتصال أو الصلاحيات. تحقق من قائمة عروضك قبل إعادة المحاولة.');return}
  alert('تم إرسال العرض للعميل.');
  tab='bids';
  await load(defs[current]);
 }catch{
  alert('تعذر تأكيد إرسال العرض. راجع قائمة عروضك قبل إعادة المحاولة لتجنب إرسال عرض مكرر.');
 }finally{
  if(button.isConnected){button.disabled=false;button.textContent=originalText}
 }
}
async function mgAccept(id,ride){const r=await sb.rpc('accept_mantigo_bid_backend',{p_user_id:user.id,p_ride_id:ride,p_bid_id:id});if(r.error)return alert('تعذر تنفيذ العملية بسبب الاتصال أو الصلاحيات. تحقق من البيانات ثم حاول مرة أخرى.');await load(defs[current])}
async function mgApplyCaptain(){const model=(document.getElementById('mgApplyModel')?.value||'').trim();const plate=(document.getElementById('mgApplyPlate')?.value||'').trim();const areas=(document.getElementById('mgApplyAreas')?.value||'').split(/[،,]/).map(x=>x.trim()).filter(Boolean);if(!model||!plate)return alert('أكمل موديل المركبة ورقم اللوحة.');const r=await sb.rpc('submit_mantigo_captain_application',{p_user_id:user.id,p_vehicle_category:document.getElementById('mgApplyVehicle').value,p_vehicle_model:model,p_vehicle_plate:plate,p_service_areas:areas});if(r.error)return alert('تعذر تنفيذ العملية بسبب الاتصال أو الصلاحيات. تحقق من البيانات ثم حاول مرة أخرى.');alert('تم إرسال طلب الكابتن للمراجعة.');await load(defs[current])}
async function mgSetPresence(status){const p=rows.mantigo_captain_profile;if(!p)return alert('لا يوجد ملف كابتن مرتبط بهذا الحساب.');if(status==='AVAILABLE'&&(!p.status||p.status!=='ACTIVE'||p.verification_status!=='VERIFIED'))return alert('الحساب لم يتم اعتماده ككابتن موثق بعد.');let pos=null;if(status!=='OFFLINE')pos=await mgGetCurrentPosition();const r=await sb.rpc('update_mantigo_captain_presence_backend',{p_user_id:user.id,p_availability_status:status,p_current_lat:pos?.lat??null,p_current_lon:pos?.lon??null});if(r.error)return alert('تعذر تنفيذ العملية بسبب الاتصال أو الصلاحيات. تحقق من البيانات ثم حاول مرة أخرى.');await load(defs[current])}
async function mgTransition(ride,status){let reason=null;if(['FAILED','SHOW_NO','CANCELLED'].includes(status)){const label=status==='SHOW_NO'?'سبب عدم الحضور:':status==='CANCELLED'?'سبب إلغاء الرحلة:':'سبب تعذر تنفيذ الرحلة:';reason=prompt(label);if(reason===null)return;if(!reason.trim())return alert('يجب إدخال سبب واضح.');}const r=await sb.rpc('update_mantigo_trip_status_backend',{p_user_id:user.id,p_ride_id:ride,p_target_status:status,p_reason:reason});if(r.error)return alert('تعذر تنفيذ العملية بسبب الاتصال أو الصلاحيات. تحقق من البيانات ثم حاول مرة أخرى.');await load(defs[current])}
async function mgCashPay(ride){if(!confirm('تأكيد الدفع النقدي للرحلة؟'))return;const r=await sb.rpc('confirm_mantigo_cash_payment_backend',{p_user_id:user.id,p_ride_id:ride});if(r.error)return alert('تعذر تنفيذ العملية بسبب الاتصال أو الصلاحيات. تحقق من البيانات ثم حاول مرة أخرى.');alert('تم تأكيد الدفع النقدي.');await load(defs[current])}
async function mgCardPay(ride){try{const s=await sb.auth.getSession();const token=s.data?.session?.access_token;if(!token)return alert('انتهت جلسة الدخول. سجل الدخول ثم حاول مرة أخرى.');const res=await fetch((window.MANTIQATIX_CONFIG?.supabaseUrl||'')+'/functions/v1/mantigo-payment-intent',{method:'POST',headers:{Authorization:'Bearer '+token,'Content-Type':'application/json',apikey:window.MANTIQATIX_CONFIG?.supabaseKey||''},body:JSON.stringify({rideId:ride})});const data=await res.json().catch(()=>({}));if(!res.ok||!data.checkoutUrl)return alert('تعذر بدء الدفع الإلكتروني. تحقق من حالة الرحلة والاتصال ثم حاول مرة أخرى.');window.location.href=data.checkoutUrl}catch{return alert('تعذر الاتصال بخدمة الدفع الإلكتروني. لم يتم تأكيد بدء الدفع؛ راجع حالة الرحلة قبل إعادة المحاولة.')}}
async function mgRate(ride){const v=Number(prompt('قيّم الرحلة من 1 إلى 5'));if(!v)return;if(v<1||v>5)return alert('التقييم من 1 إلى 5.');const r=await sb.rpc('mantigo_rate_ride',{p_ride_id:ride,p_rating:v,p_comment:''});if(r.error)return alert('تعذر تنفيذ العملية بسبب الاتصال أو الصلاحيات. تحقق من البيانات ثم حاول مرة أخرى.');alert('تم تسجيل التقييم.');await load(defs[current])}
function mantigoWorkspace(){const mine=(rows.mantigo_customer_tracking||[]).map(x=>x.ride||x).filter(r=>r.customer_id===user.id);const captain=(rows.mantigo_captain_rides||[]);const e=rows.mantigo_captain_earnings||{};return shell({key:'MANTIGO',desc:'تشغيل الرحلات والعروض'},tabs(defs['MantiGO والنقل'])+'<div class="cards"><article class="card"><div class="metric">'+mine.length+'</div><div class="muted">رحلاتي كعميل</div></article><article class="card"><div class="metric">'+captain.length+'</div><div class="muted">رحلاتي ككابتن</div></article><article class="card"><div class="metric">'+money(e.net||0)+'</div><div class="muted">صافي مستحقات الكابتن</div></article></div>')}
function mantigoRequestView(){return shell({key:'MANTIGO',desc:'اطلب رحلتك بسهولة، واستقبل عروض الكباتن قبل الاختيار.'},'<div class="mg-request-tabs"><button class="btn btn-primary">🚗 طلب رحلة</button><button class="btn btn-outline" data-op-tab="myrides">رحلاتي</button></div>'+mantigoRideForm())}
function mantigoOpenView(){return shell({key:'MANTIGO',desc:'الطلبات المفتوحة للكباتن.'},tabs(defs['MantiGO والنقل'])+((rows.mantigo_open&&rows.mantigo_open.length)?mantigoOpenRides():'<div class="empty-state">جارٍ تحميل الطلبات المفتوحة...</div>'))}
function mantigoCustomerTripTimeline(r,fin,acceptedBid){
  const stages=[['ACCEPTED','تم قبول الكابتن'],['ARRIVED','الكابتن وصل'],['STARTED','بدأت الرحلة'],['IN_PROGRESS','الرحلة جارية'],['COMPLETED','اكتملت الرحلة']];
  const order={ACCEPTED:0,ARRIVED:1,STARTED:2,IN_PROGRESS:3,COMPLETED:4};
  const currentIndex=order[r.status]??-1;
  const timeline=stages.map((s,i)=>'<div style="display:flex;gap:10px;align-items:flex-start;opacity:'+(i<=currentIndex?'1':'.45')+'"><span style="width:12px;height:12px;border-radius:50%;background:'+(i<=currentIndex?'#12b76a':'#d0d5dd')+';margin-top:5px;flex:0 0 auto"></span><div><strong>'+s[1]+'</strong><div class="muted">'+(i<currentIndex?'تم':i===currentIndex?'الحالة الحالية':'بانتظار التحديث')+'</div></div></div>').join('');
  return '<section class="card" style="border:2px solid #12b76a;background:#fcfffd"><div class="eyebrow">MantiGO · متابعة مباشرة</div><h3 style="margin-bottom:6px">'+esc(r.pickup_location)+' ← '+esc(r.destination_location)+'</h3><div class="muted">'+esc(mantigoStatus(r.status))+' · '+money(r.proposed_price)+'</div><div style="display:grid;gap:9px;margin:16px 0">'+timeline+'</div>'+(acceptedBid?'<div class="card" style="background:#fff"><strong>الكابتن المقبول</strong><div style="margin-top:6px">'+esc(acceptedBid.captain_name||'كابتن MantiGO')+(acceptedBid.vehicle_model?' · '+esc(acceptedBid.vehicle_model):'')+(acceptedBid.vehicle_plate?' · '+esc(acceptedBid.vehicle_plate):'')+'</div><div class="muted">'+esc(acceptedBid.captain_phone||'')+(acceptedBid.eta_minutes!=null?' · الوصول المتوقع '+esc(acceptedBid.eta_minutes)+' دقيقة':'')+'</div></div>':'')+(fin?'<div class="muted" style="margin-top:10px">الدفع: '+esc(fin.payment_status)+' · التسوية: '+esc(fin.settlement_status)+'</div>':'')+'</section>';
}
function mantigoReceipt(r,fin,acceptedBid){ return '<div class="card" style="margin-top:12px;background:#fff;border:1px solid #e4e7ec"><div style="display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap"><div><div class="eyebrow">إيصال MantiGO</div><strong>رحلة مكتملة</strong></div><span class="badge">'+esc(fin?.payment_status||'—')+'</span></div><div class="grid-2" style="margin-top:12px"><div><small class="muted">المسار</small><div>'+esc(r.pickup_location)+' ← '+esc(r.destination_location)+'</div></div><div><small class="muted">قيمة الرحلة</small><div><strong>'+money(fin?.gross_amount??r.proposed_price)+'</strong></div></div><div><small class="muted">طريقة الدفع</small><div>'+esc(fin?.payment_method==='CASH'?'نقدي':fin?.payment_method==='CARD'?'بطاقة':'—')+'</div></div><div><small class="muted">مرجع الدفع</small><div>'+esc(fin?.payment_reference||'—')+'</div></div><div><small class="muted">الكابتن</small><div>'+esc(acceptedBid?.captain_name||'—')+'</div></div><div><small class="muted">رقم الرحلة</small><div>'+esc(r.id)+'</div></div></div></div>'; }function mantigoMyRidesView(){const tracking=rows.mantigo_customer_tracking||[];const mine=tracking.map(x=>x.ride||x).filter(r=>r.customer_id===user.id);const active=mine.filter(r=>['ACCEPTED','ARRIVED','STARTED','IN_PROGRESS'].includes(r.status));return shell({key:'MANTIGO',desc:'رحلاتك كعميل وحالة التنفيذ.'},tabs(defs['MantiGO والنقل'])+(active.length?'<div style="display:grid;gap:14px;margin:14px 0">'+active.map(r=>{const fin=(rows.mantigo_financial_ledger||[]).find(f=>f.ride_id===r.id);const acceptedBid=(rows.mantigo_bids||[]).find(b=>b.ride_id===r.id&&b.status==='ACCEPTED');return mantigoCustomerTripTimeline(r,fin,acceptedBid)}).join('')+'</div>':'')+'<div class="cards">'+(mine.map(r=>{const packed=tracking.find(x=>(x.ride||x).id===r.id);const bids=packed?.bids||((rows.mantigo_bids||[]).filter(b=>b.ride_id===r.id));const fin=(rows.mantigo_financial_ledger||[]).find(f=>f.ride_id===r.id);let action=r.status==='COMPLETED'?'<button class="btn btn-outline" data-mg-rate="'+esc(r.id)+'">قيّم الرحلة</button>':r.status==='OPEN'||r.status==='OPEN_FOR_BIDS'?'<button class="btn btn-outline" data-mg-cancel="'+esc(r.id)+'">إلغاء الطلب</button>':'';if(['ACCEPTED','ARRIVED'].includes(r.status)&&fin&&['REQUIRED','PENDING'].includes(fin.payment_status))action+='<button class="btn btn-primary" data-mg-card-pay="'+esc(r.id)+'">دفع إلكتروني</button><button class="btn btn-outline" data-mg-cash-pay="'+esc(r.id)+'">تأكيد نقدي</button>';if(fin)action+='<div class="muted" style="margin-top:6px">حالة الدفع: '+esc(fin.payment_status)+'</div>';return '<article class="card"><h3>'+esc(r.pickup_location)+' ← '+esc(r.destination_location)+'</h3><div class="muted">'+money(r.proposed_price)+' · '+esc(mantigoStatus(r.status))+'</div>'+(r.status==='COMPLETED'&&fin?mantigoReceipt(r,fin,((rows.mantigo_bids||[]).find(b=>b.ride_id===r.id&&b.status==='ACCEPTED'))):'')+'<div class="table-wrap" style="margin-top:8px"><table><thead><tr><th>الكابتن</th><th>العرض</th><th>الوصول</th><th></th></tr></thead><tbody>'+bids.map(b=>'<tr><td>'+esc(b.captain_name)+'<br><small>'+esc(b.vehicle_model||'')+'</small></td><td>'+money(b.offered_price)+'</td><td>'+esc(b.eta_minutes)+' د</td><td>'+(b.status==='OFFERED'&&['OPEN','OPEN_FOR_BIDS'].includes(r.status)?'<button class="btn btn-primary" data-mg-accept="'+esc(b.id)+'" data-mg-ride="'+esc(r.id)+'">قبول</button>':esc(mantigoStatus(b.status)))+'</td></tr>').join('')+'</tbody></table></div>'+action+'</article>'}).join('')||'<div class="empty-state">لا توجد رحلات بعد.</div>')+'</div>')}
function mantigoBidsView(){const profile=rows.mantigo_captain_profile;const presence=profile?'<article class="card" style="margin-bottom:14px"><div class="eyebrow">حالة الكابتن</div><h3>'+(profile.vehicle_model?esc(profile.vehicle_model):'ملف الكابتن')+'</h3><div class="muted">'+esc(profile.status||'—')+' · '+esc(profile.verification_status||'—')+' · '+esc(profile.vehicle_category||'—')+'</div><div class="action-bar" style="margin-top:10px"><button class="btn '+(profile.availability_status==='AVAILABLE'?'btn-primary':'btn-outline')+'" data-mg-presence="AVAILABLE">متاح لاستقبال الرحلات</button><button class="btn '+(profile.availability_status==='BUSY'?'btn-primary':'btn-outline')+'" data-mg-presence="BUSY">مشغول</button><button class="btn '+(profile.availability_status==='OFFLINE'?'btn-primary':'btn-outline')+'" data-mg-presence="OFFLINE">غير متاح</button></div></article>':'<article class="card" style="margin-bottom:14px"><div class="eyebrow">MantiGO Captain</div><h3>انضم ككابتن</h3><p class="muted">قدّم بيانات مركبتك مرة واحدة، وسيتم مراجعتها قبل السماح باستقبال الرحلات.</p><div class="grid-2" style="margin-top:12px"><select id="mgApplyVehicle" class="input"><option value="CAR">سيارة</option><option value="TAXI">تاكسي</option><option value="VAN">فان</option><option value="MOTORCYCLE">موتوسيكل</option></select><input id="mgApplyModel" class="input" placeholder="موديل المركبة"><input id="mgApplyPlate" class="input" placeholder="رقم اللوحة"><input id="mgApplyAreas" class="input" placeholder="مناطق الخدمة، مثال: الجيزة، القاهرة"></div><button class="btn btn-primary" style="margin-top:12px" id="mgApplyCaptain">إرسال طلب الكابتن</button></article>';const accepted=(rows.mantigo_captain_rides||[]);const cards=accepted.map(r=>{let actions='';if(r.status==='ACCEPTED')actions='<button class="btn btn-primary" data-mg-status="ARRIVED" data-mg-ride="'+esc(r.id)+'">وصلت</button><button class="btn btn-outline" data-mg-status="SHOW_NO" data-mg-ride="'+esc(r.id)+'">لم يحضر العميل</button><button class="btn btn-outline" data-mg-status="CANCELLED" data-mg-ride="'+esc(r.id)+'">إلغاء</button>';else if(r.status==='ARRIVED')actions='<button class="btn btn-primary" data-mg-status="STARTED" data-mg-ride="'+esc(r.id)+'">بدء الرحلة</button><button class="btn btn-outline" data-mg-status="SHOW_NO" data-mg-ride="'+esc(r.id)+'">لم يحضر العميل</button><button class="btn btn-outline" data-mg-status="CANCELLED" data-mg-ride="'+esc(r.id)+'">إلغاء</button>';else if(r.status==='STARTED')actions='<button class="btn btn-primary" data-mg-status="IN_PROGRESS" data-mg-ride="'+esc(r.id)+'">الرحلة بدأت</button><button class="btn btn-outline" data-mg-status="FAILED" data-mg-ride="'+esc(r.id)+'">تعذر التنفيذ</button>';else if(r.status==='IN_PROGRESS')actions='<button class="btn btn-primary" data-mg-status="COMPLETED" data-mg-ride="'+esc(r.id)+'">إنهاء الرحلة</button><button class="btn btn-outline" data-mg-status="FAILED" data-mg-ride="'+esc(r.id)+'">تعذر التنفيذ</button>';return '<article class="card"><h3>'+esc(r.pickup_location)+' ← '+esc(r.destination_location)+'</h3><div class="muted">'+money(r.proposed_price)+' · '+esc(mantigoStatus(r.status))+'</div><div class="action-bar" style="margin-top:10px">'+actions+(['ACCEPTED','ARRIVED','STARTED','IN_PROGRESS'].includes(r.status)?'<button class="btn btn-outline" data-mg-status="FAILED" data-mg-ride="'+esc(r.id)+'">تعذر التنفيذ</button>':'')+'</div></article>'}).join('');return shell({key:'MANTIGO',desc:'تقديم العروض ومتابعة الرحلات المقبولة.'},tabs(defs['MantiGO والنقل'])+(cards||'<div class="empty-state">لا توجد رحلات مقبولة لك حاليًا.</div>')+'<div style="margin-top:16px">'+((rows.mantigo_open||[]).length?mantigoOpenRides():'')+'</div>')}
function liveColumnLabel(key){const labels={id:'المعرف',name:'الاسم',name_ar:'الاسم بالعربية',name_en:'الاسم بالإنجليزية',title:'العنوان',description:'الوصف',status:'الحالة',created_at:'تاريخ الإنشاء',updated_at:'آخر تحديث',user_id:'معرف المستخدم',business_id:'معرف النشاط',branch_id:'معرف الفرع',customer_id:'معرف العميل',provider_id:'معرف مقدم الخدمة',service_id:'معرف الخدمة',category:'التصنيف',category_code:'كود التصنيف',code:'الكود',sku:'كود الصنف',price:'السعر',unit_price:'سعر الوحدة',currency:'العملة',quantity:'الكمية',total:'الإجمالي',amount:'المبلغ',budget_min:'الميزانية من',budget_max:'الميزانية إلى',service_area:'نطاق الخدمة',required_services:'الخدمات المطلوبة',source:'المصدر',email:'البريد الإلكتروني',phone:'الهاتف',role:'الدور',is_active:'نشط',is_verified:'موثق',is_featured:'مميز',appointment_at:'موعد الحجز',scheduled_at:'الموعد المحدد',payment_status:'حالة الدفع',order_status:'حالة الطلب',type:'النوع',item_type:'نوع الصنف',version:'الإصدار',effective_from:'ساري من'};return labels[key]||String(key).replace(/_/g,' ')}
function genericLiveTable(t,query='',requestedPage=0){
 const source=rows[t]||[],keys=Object.keys(source[0]||{}).slice(0,8),needle=String(query||'').trim().toLocaleLowerCase(),pageSize=25;
 const filtered=source.filter(r=>!needle||keys.some(k=>String(r[k]??'').toLocaleLowerCase().includes(needle)));
 const pageCount=Math.max(1,Math.ceil(filtered.length/pageSize)),page=Math.min(Math.max(0,Number(requestedPage)||0),pageCount-1),visible=filtered.slice(page*pageSize,(page+1)*pageSize);
 const head='<div class="muted" role="status">عرض '+filtered.length+' من '+source.length+' سجل مرئي · صفحة '+(page+1)+' من '+pageCount+'</div>';
 if(!keys.length)return head+'<div class="empty-state">لا توجد بيانات فعلية ضمن نطاق الصلاحية.</div>';
 const body=visible.length?visible.map(r=>'<tr>'+keys.map(k=>'<td>'+esc(r[k]??'—')+'</td>').join('')+'</tr>').join(''):'<tr><td colspan="'+keys.length+'">لا توجد نتائج مطابقة للبحث.</td></tr>';
 const pager=filtered.length>pageSize?'<nav class="action-bar" aria-label="التنقل بين صفحات السجلات"><button type="button" class="btn btn-outline" data-live-page="'+(page-1)+'" data-live-table="'+esc(t)+'" aria-label="الصفحة السابقة"'+(page===0?' disabled':'')+'>السابق</button><span class="muted">صفحة '+(page+1)+' من '+pageCount+'</span><button type="button" class="btn btn-outline" data-live-page="'+(page+1)+'" data-live-table="'+esc(t)+'" aria-label="الصفحة التالية"'+(page>=pageCount-1?' disabled':'')+'>التالي</button></nav>':'';
 return head+'<div class="table-wrap"><table aria-label="سجلات '+esc(t)+'"><thead><tr>'+keys.map(k=>'<th>'+esc(liveColumnLabel(k))+'</th>').join('')+'</tr></thead><tbody>'+body+'</tbody></table></div>'+pager;
}
function genericLiveView(d){
 const blocks=d.tables.map(t=>{
  const head='<section class="card" style="margin:12px 0"><h3>'+esc(t)+'</h3>';
  if(BACKEND_ONLY_TABLES.has(t))return head+'<div class="notice">الوصول لهذا الجدول يتم عبر مسار خلفي مصرح به فقط.</div></section>';
  if(loadErrors[t])return head+'<div class="notice" role="alert">تعذر تحميل البيانات؛ لم يتم اعتبارها فارغة. أعد المحاولة أو راجع الصلاحيات.</div></section>';
  return head+'<label for="live-search-'+esc(t)+'">البحث في السجلات<input class="input" id="live-search-'+esc(t)+'" type="search" maxlength="120" data-live-search="'+esc(t)+'" aria-label="البحث في سجلات '+esc(t)+'" placeholder="ابحث في الحقول المعروضة"/></label><div data-live-results="'+esc(t)+'">'+genericLiveTable(t)+'</div></section>';
 }).join('');
 return shell(d,tabs(d)+'<div class="notice">البيانات تخضع لصلاحيات الحساب. البحث يقتصر على الحقول المعروضة؛ أخطاء القراءة والجداول المخصصة للمسار الخلفي لا تظهر كنتائج فارغة.</div>'+(blocks||'<div class="empty-state">لا توجد بيانات فعلية ضمن نطاق الصلاحية.</div>'));
}
