function marketingLeadTable(query=''){const term=String(query||'').trim().toLocaleLowerCase('ar-EG');const filtered=(rows.marketing_leads||[]).filter(r=>[r.title,r.description,r.service_area,r.status,r.source,...(r.required_services||[])].filter(Boolean).join(' ').toLocaleLowerCase('ar-EG').includes(term));return table([['عنوان الطلب','title'],['الخدمات المطلوبة',r=>(r.required_services||[]).join('، ')||'—'],['الميزانية',r=>money(r.budget_min)+' – '+money(r.budget_max)],['نطاق الخدمة','service_area'],['الحالة','status'],['تاريخ الطلب',r=>r.created_at?new Date(r.created_at).toLocaleDateString('ar-EG'):'—']],filtered)}
function leadForm(){const businesses=[...new Map(memberships.filter(m=>m.business_id).map(m=>[m.business_id,m])).values()];const selectedBusiness=businesses.some(m=>m.business_id===membership?.business_id)?membership.business_id:(businesses.length===1?businesses[0].business_id:'');const businessField=businesses.length>1?'<label for="mlBusiness">النشاط التجاري المطلوب<select id="mlBusiness" class="input" required aria-describedby="mlHelp mlStatus"><option value="">اختر النشاط التجاري</option>'+businesses.map((m,i)=>'<option value="'+esc(m.business_id)+'" '+(m.business_id===selectedBusiness?'selected':'')+' title="'+esc(m.business_id)+'">النشاط '+(i+1)+' · '+esc(m.business_id.slice(-8))+'</option>').join('')+'</select></label>':(businesses.length===1?'<input type="hidden" id="mlBusiness" value="'+esc(businesses[0].business_id)+'">':'');const membershipNotice=membershipLoadError?'<div class="notice" role="alert">تعذر التحقق من عضويات الحساب. تم إيقاف إرسال الطلب مؤقتًا حتى لا يُربط بنشاط غير صحيح. أعد تحميل الموديول أو راجع صلاحيات الحساب.</div>':'';return '<div class="card" style="margin:16px 0"><h3>طلب خدمة تسويق</h3>'+membershipNotice+'<p id="mlHelp" class="muted">أدخل تفاصيل الطلب والميزانية بالجنيه المصري. لن يتم إرسال الطلب إلا بعد التحقق من البيانات.</p><div class="grid-2">'+businessField+'<label for="mlTitle">عنوان الطلب<input id="mlTitle" class="input" maxlength="160" required aria-describedby="mlHelp mlStatus" placeholder="مثال: إدارة حملة إعلانية"></label><label for="mlArea">نطاق الخدمة<input id="mlArea" class="input" maxlength="120" aria-describedby="mlHelp" placeholder="المدينة أو نطاق الاستهداف"></label><label for="mlServices">الخدمات المطلوبة (افصل بينها بفاصلة)<input id="mlServices" class="input" maxlength="800" aria-describedby="mlHelp mlStatus" placeholder="إدارة الحملات، تصميم المحتوى، الإعلانات"></label><label for="mlMin">الميزانية من (جنيه)<input id="mlMin" class="input" type="number" min="0" step="0.01" inputmode="decimal" aria-describedby="mlHelp" placeholder="0"></label><label for="mlMax">الميزانية إلى (جنيه)<input id="mlMax" class="input" type="number" min="0" step="0.01" inputmode="decimal" aria-describedby="mlHelp" placeholder="0"></label><label for="mlDesc">تفاصيل الطلب<textarea id="mlDesc" class="input" maxlength="5000" required aria-describedby="mlHelp mlStatus" placeholder="الأهداف والخدمات المطلوبة"></textarea></label></div><p id="mlStatus" role="status" aria-live="polite" class="muted"></p><button class="btn btn-primary" id="save-lead" type="button" '+(membershipLoadError?'disabled aria-disabled="true"':'')+'>إنشاء طلب</button></div>'}
async function saveLead(){const button=document.getElementById('save-lead'),status=document.getElementById('mlStatus'),businessInput=document.getElementById('mlBusiness'),title=document.getElementById('mlTitle')?.value.trim()||'',description=document.getElementById('mlDesc')?.value.trim()||'',area=document.getElementById('mlArea')?.value.trim()||'',servicesRaw=document.getElementById('mlServices')?.value||'',minRaw=document.getElementById('mlMin')?.value.trim()||'',maxRaw=document.getElementById('mlMax')?.value.trim()||'';const setStatus=(message,isError=false)=>{if(status){status.textContent=message;status.style.color=isError?'#b42318':''}};if(!button||button.disabled)return;if(membershipLoadError){setStatus('لا يمكن إرسال الطلب قبل التحقق من عضويات الحساب.',true);return}const min=minRaw===''?0:Number(minRaw),max=maxRaw===''?0:Number(maxRaw);if(memberships.filter(m=>m.business_id).length>1&&!businessInput?.value){setStatus('اختر النشاط التجاري الذي يخصه طلب التسويق.',true);return}if(!title||!description){setStatus('أكمل عنوان الطلب والتفاصيل قبل الإرسال.',true);return}if(title.length>160||area.length>120||description.length>5000||servicesRaw.length>800){setStatus('تجاوز أحد الحقول الحد المسموح للطول.',true);return}const requiredServices=[...new Set(servicesRaw.split(',').map(x=>x.trim()).filter(Boolean))];if(requiredServices.length>10||requiredServices.some(x=>x.length>80)){setStatus('أدخل حتى 10 خدمات، على ألا يتجاوز اسم كل خدمة 80 حرفًا.',true);return}if(!Number.isFinite(min)||!Number.isFinite(max)||min<0||max<0){setStatus('أدخل ميزانية صحيحة غير سالبة.',true);return}if(max<min){setStatus('الميزانية الدنيا لا يمكن أن تتجاوز الميزانية القصوى.',true);return}const p={title,description,budget_min:min,budget_max:max,required_services:requiredServices,service_area:area};const businessId=businessInput?.value||scope()?.business_id;if(businessId)p.business_id=businessId;button.disabled=true;button.textContent='جارٍ إرسال الطلب…';setStatus('جارٍ التحقق من الطلب وإرساله بأمان.');try{const r=await sb.functions.invoke('marketing-lead-create',{body:p});if(r.error||r.data?.error||r.data?.ok!==true||!r.data?.lead?.id){const code=typeof r.data?.error==='string'?r.data.error:'';const messages={business_selection_required:'اختر النشاط التجاري المطلوب من محدد النشاط ثم أعد الإرسال.',business_not_authorized:'لا تملك صلاحية إنشاء طلب لهذا النشاط التجاري.',unauthorized:'انتهت الجلسة أو لم يتم تسجيل الدخول. سجل الدخول ثم حاول مرة أخرى.',invalid_budget:'راجع الميزانية الدنيا والقصوى ثم أعد المحاولة.',invalid_title:'أدخل عنوانًا صحيحًا لا يتجاوز 200 حرف.',invalid_description:'أدخل تفاصيل الطلب ولا تتجاوز 5000 حرف.',invalid_service_area:'أدخل نطاق الخدمة كنص لا يتجاوز 200 حرف.',invalid_required_services:'راجع الخدمات المطلوبة: حتى 10 خدمات وبحد أقصى 80 حرفًا لكل خدمة.',server_configuration_error:'خدمة طلبات التسويق غير متاحة حاليًا.'};setStatus(messages[code]||'تعذر تأكيد إنشاء طلب التسويق. لم نعرض الطلب كناجح؛ تحقق من قائمة الطلبات قبل إعادة المحاولة.',true);return}setStatus('تم إرسال طلب التسويق بنجاح.');await load(defs[current])}catch(error){setStatus('تعذر الاتصال بالخدمة. لم نتمكن من تأكيد إرسال الطلب؛ راجع الطلبات قبل إعادة المحاولة.',true)}finally{button.disabled=false;button.textContent='إنشاء طلب'}}


function educationWorkspace(){
 const schools=rows.school_profiles||[], teachers=rows.teacher_profiles||[], requests=rows.education_requests||[];
 const formMarkup=(id,type,name,buttonText)=>'<button type="button" class="btn btn-primary" style="margin-top:10px" data-edu-request="'+id+'" data-edu-type="'+type+'" data-edu-name="'+name+'" aria-expanded="false" aria-controls="edu-form-'+type+'-'+id+'">'+buttonText+'</button><form class="card" id="edu-form-'+type+'-'+id+'" data-edu-form="'+id+'" data-edu-type="'+type+'" hidden style="margin-top:12px"><h4>تفاصيل الطلب</h4><label for="edu-student-'+id+'">اسم الطالب</label><input class="input" id="edu-student-'+id+'" name="studentName" maxlength="120" required placeholder="اسم الطالب"/><label for="edu-subject-'+id+'">'+(type==='TEACHER'?'المادة والصف المطلوبان':'المرحلة الدراسية المطلوبة')+'</label><input class="input" id="edu-subject-'+id+'" name="subject" maxlength="200" required placeholder="اكتب التفاصيل المطلوبة"/><p class="muted" data-edu-status role="status" aria-live="polite"></p><button type="submit" class="btn btn-primary">إرسال الطلب</button></form>';
 const schoolCards=schools.filter(x=>x.is_available!==false).map(x=>{const id=esc(x.id),name=esc(x.name||'مدرسة');return '<article class="card"><div class="eyebrow">مدرسة</div><h3>'+name+'</h3><div class="muted">'+esc(x.school_type||'')+' · '+esc(x.location||'')+'</div><div class="muted">'+(x.tuition_fee!=null?'المصروفات: '+money(x.tuition_fee):'')+'</div>'+formMarkup(id,'SCHOOL',name,'طلب معلومات/تقديم')+'</article>'}).join('');
 const teacherCards=teachers.filter(x=>x.is_available!==false).map(x=>{const id=esc(x.id),name=esc(x.name||'مدرس');return '<article class="card"><div class="eyebrow">مدرس</div><h3>'+name+'</h3><div class="muted">'+esc(x.subject||'')+' · '+esc(x.location||'')+'</div><div class="muted">'+(x.hourly_rate!=null?'السعر بالساعة: '+money(x.hourly_rate):'')+'</div>'+formMarkup(id,'TEACHER',name,'طلب درس/تواصل')+'</article>'}).join('');
 const my=requests.filter(x=>x.requester_user_id===user.id).map(x=>'<tr><td>'+esc(x.student_name||'—')+'</td><td>'+esc(x.target_type||'—')+'</td><td>'+esc(x.subject_or_grade||'—')+'</td><td>'+esc(x.status||'—')+'</td></tr>').join('');
 return shell(defs['مدارس خاصة'],tabs(defs['مدارس خاصة'])+'<div class="notice">طلبات التعليم تُنشأ بالحساب الحالي وتخضع لصلاحيات الخادم؛ لا يتم إنشاء بيانات نيابة عن مستخدم آخر.</div><div class="cards">'+(schoolCards+teacherCards||'<div class="empty-state">لا توجد جهات تعليمية متاحة حاليًا.</div>')+'</div><section class="card" style="margin-top:14px"><h3>طلباتي التعليمية</h3><div class="table-wrap"><table><thead><tr><th>الطالب</th><th>النوع</th><th>المادة/المرحلة</th><th>الحالة</th></tr></thead><tbody>'+(my||'<tr><td colspan="4">لا توجد طلبات.</td></tr>')+'</tbody></table></div></section>');
}
function medicalProviderRows(){return (rows.marketing_provider_profiles||[]).filter(p=>p.status==='ACTIVE' && Array.isArray(p.specialties) && p.specialties.some(s=>/طب|طبي|كشف|أسنان|صيدل|تحاليل|أشعة|مستشفى|طوارئ/.test(String(s))));}
function medicalWorkspace(){const d=defs['المنظومة الطبية'];const providers=medicalProviderRows();const appointments=rows.medical_appointments||[];if(tab==='providers')return shell(d,tabs(d)+'<div class="cards">'+(providers.length?providers.map(p=>{const id=esc(p.id);return '<article class="card"><div class="eyebrow">خدمة طبية</div><h3>'+esc(p.name_ar||p.name_en||'مقدم خدمة')+'</h3><div class="muted">'+esc((p.specialties||[]).join(' · '))+'</div><div class="muted">'+(p.is_verified?'موثق':'غير موثق')+'</div><button type="button" class="btn btn-primary" style="margin-top:10px" data-medical-book="'+id+'" aria-expanded="false" aria-controls="medical-form-'+id+'">حجز موعد</button><form class="card" id="medical-form-'+id+'" data-medical-form="'+id+'" hidden style="margin-top:12px"><h4>بيانات الموعد</h4><label for="medical-date-'+id+'">التاريخ والوقت</label><input class="input" id="medical-date-'+id+'" name="dateTime" type="datetime-local" required/><label for="medical-reason-'+id+'">سبب الزيارة (اختياري)</label><textarea class="input" id="medical-reason-'+id+'" name="reason" maxlength="1000" rows="3" placeholder="اكتب سبب الزيارة إن رغبت"></textarea><p class="muted" data-medical-status role="status" aria-live="polite"></p><button type="submit" class="btn btn-primary">تأكيد طلب الموعد</button></form></article>'}).join(''):'<div class="empty-state">لا يوجد مقدم خدمة طبي نشط مطابق حاليًا.</div>')+'</div>');
if(tab==='appointments')return shell(d,tabs(d)+table([['الموعد','id'],['مقدم الخدمة','doctor_id'],['التاريخ',r=>r.date_time?new Date(Number(r.date_time)).toLocaleString('ar-EG'):'—'],['الحالة','status'],['السبب','reason']],appointments));
return shell(d,tabs(d)+'<div class="cards"><article class="card"><div class="metric">'+providers.length+'</div><div class="muted">مقدمو الخدمة الطبية النشطون</div></article><article class="card"><div class="metric">'+appointments.length+'</div><div class="muted">مواعيدي الظاهرة</div></article></div><p class="muted" style="margin-top:14px">الحجز يتم عبر مسار الخادم المخصص ولا يسمح للمتصفح بالكتابة المباشرة إلى سجل المواعيد.</p>')}
async function medicalBook(providerId,form){const p=medicalProviderRows().find(x=>String(x.id)===String(providerId));const status=form?.querySelector('[data-medical-status]'),submit=form?.querySelector('button[type="submit"]');const setStatus=(message,isError=false)=>{if(status){status.textContent=message;status.setAttribute('role',isError?'alert':'status')}};if(!p||!p.business_id){setStatus('بيانات مقدم الخدمة غير مكتملة؛ لم يتم إرسال الحجز.',true);return}if(!form||!form.reportValidity())return;const raw=String(form.elements.dateTime?.value||'');const dt=new Date(raw);const reason=String(form.elements.reason?.value||'').trim();if(!raw||Number.isNaN(dt.getTime())){setStatus('اختر تاريخًا ووقتًا صحيحين للموعد.',true);return}if(dt.getTime()<=Date.now()){setStatus('اختر موعدًا في المستقبل.',true);return}if(reason.length>1000){setStatus('سبب الزيارة يجب ألا يتجاوز 1000 حرف.',true);return}if(submit){submit.disabled=true;submit.textContent='جارٍ إرسال طلب الموعد…'}setStatus('جارٍ إرسال طلب الموعد…');try{const r=await sb.rpc('create_medical_appointment_backend',{p_user_id:user.id,p_appointment_id:crypto.randomUUID(),p_business_id:p.business_id,p_doctor_id:String(p.id),p_date_time:dt.getTime(),p_reason:reason});if(r.error){setStatus('تعذر إرسال طلب الموعد بسبب الاتصال أو الصلاحيات. تحقق من البيانات ثم حاول مرة أخرى.',true);return}setStatus('تم إرسال طلب الموعد بنجاح.');tab='appointments';await load(defs[current])}catch{setStatus('تعذر تأكيد إرسال طلب الموعد. راجع قائمة المواعيد قبل إعادة المحاولة.',true)}finally{if(submit){submit.disabled=false;submit.textContent='تأكيد طلب الموعد'}}}
async function createEducationRequest(targetId,targetType,form){
 const status=form?.querySelector('[data-edu-status]'),submit=form?.querySelector('button[type="submit"]');
 const setStatus=(message,isError=false)=>{if(status){status.textContent=message;status.setAttribute('role',isError?'alert':'status')}};
 if(!form||!form.reportValidity())return;
 const student=String(form.elements.studentName?.value||'').trim(),subject=String(form.elements.subject?.value||'').trim();
 if(!student||!subject){setStatus('أكمل اسم الطالب والمادة أو المرحلة المطلوبة.',true);return}
 if(student.length>120||subject.length>200){setStatus('تجاوز أحد الحقول الحد المسموح للطول.',true);return}
 if(submit){submit.disabled=true;submit.textContent='جارٍ إرسال الطلب…'}
 setStatus('جارٍ إرسال الطلب…');
 try{
  const r=await sb.rpc('create_education_request_backend',{p_target_id:targetId,p_target_type:targetType,p_student_name:student,p_subject_or_grade:subject});
  if(r.error){setStatus('تعذر إنشاء الطلب بسبب الاتصال أو الصلاحيات. تحقق من البيانات ثم حاول مرة أخرى.',true);return}
  setStatus('تم إرسال الطلب بنجاح.');
  await load(defs['مدارس خاصة']);tab='overview';render();
 }catch{setStatus('تعذر تأكيد إرسال الطلب. راجع طلباتك قبل إعادة المحاولة.',true)}
 finally{if(submit){submit.disabled=false;submit.textContent='إرسال الطلب'}}
}
function jobsWorkspace(){
 const jobs=(rows.jobs||[]).filter(j=>j.is_active!==false);
 const apps=rows.job_applications||[];
 const mine=new Set(apps.filter(a=>a.applicant_user_id===user.id).map(a=>String(a.job_id)));
 const name=esc(user?.user_metadata?.full_name||user?.user_metadata?.name||'غير محدد');
 const phone=esc(user?.user_metadata?.phone||'غير محدد');
 const cards=jobs.map(j=>{
   const applied=mine.has(String(j.id));
   const id=esc(j.id);
   return '<article class="card"><div class="eyebrow">وظيفة فعلية</div><h3>'+esc(j.title||'وظيفة')+'</h3><div class="muted">'+esc(j.company_name||j.employer_name||'')+' · '+esc(j.location||'')+' · '+esc(j.job_type||'')+'</div><p style="white-space:pre-wrap">'+esc(j.description||'')+'</p><div class="muted">'+(j.salary_range?'الراتب: '+esc(j.salary_range):'')+'</div><div class="action-bar" style="margin-top:12px">'+(applied?'<span class="badge">تم التقديم</span>':'<button type="button" class="btn btn-primary" data-job-apply="'+id+'" aria-expanded="false" aria-controls="job-form-'+id+'">تقديم الآن</button>')+'</div>'+(applied?'':'<form class="card" id="job-form-'+id+'" data-job-form="'+id+'" hidden style="margin-top:14px"><h4>بيانات التقديم</h4><p class="muted">الاسم: '+name+' · رقم التواصل: '+phone+'</p><label for="job-qualifications-'+id+'">المؤهلات والخبرة</label><textarea class="input" id="job-qualifications-'+id+'" name="qualifications" maxlength="2000" required rows="3" placeholder="اكتب مؤهلاتك وخبرتك"></textarea><label for="job-summary-'+id+'">ملخص السيرة الذاتية</label><textarea class="input" id="job-summary-'+id+'" name="summary" maxlength="5000" required rows="4" placeholder="اكتب خبراتك ومهاراتك المهمة"></textarea><p class="muted" data-job-status role="status" aria-live="polite"></p><button type="submit" class="btn btn-primary">إرسال التقديم</button></form>')+'</article>';
 }).join('');
 return shell(defs['الوظائف'],tabs(defs['الوظائف'])+'<div class="notice">التقديم يتم بالحساب الحالي وبسياسة الصلاحيات الفعلية. راجع بيانات التواصل في حسابك قبل الإرسال.</div><div class="cards">'+(cards||'<div class="empty-state">لا توجد وظائف نشطة حاليًا.</div>')+'</div>');
}
async function applyJob(jobId,form){
 const existing=(rows.job_applications||[]).find(a=>String(a.job_id)===String(jobId)&&a.applicant_user_id===user.id);
 const status=form?.querySelector('[data-job-status]');
 const submit=form?.querySelector('button[type="submit"]');
 const setStatus=(message,isError=false)=>{if(status){status.textContent=message;status.setAttribute('role',isError?'alert':'status')}};
 if(existing){setStatus('تم التقديم على هذه الوظيفة بالفعل.',true);return}
 if(!form||!form.reportValidity())return;
 const qualifications=String(form.elements.qualifications?.value||'').trim();
 const summary=String(form.elements.summary?.value||'').trim();
 if(!qualifications||!summary){setStatus('أدخل المؤهلات وملخص السيرة الذاتية قبل الإرسال.',true);return}
 if(qualifications.length>2000||summary.length>5000){setStatus('تجاوز أحد الحقول الحد المسموح للطول.',true);return}
 const p={p_user_id:user.id,p_job_id:jobId,p_applicant_name:user?.user_metadata?.full_name||user?.user_metadata?.name||'',p_applicant_phone:user?.user_metadata?.phone||'',p_qualifications:qualifications,p_cv_summary_text:summary};
 if(submit){submit.disabled=true;submit.textContent='جارٍ إرسال التقديم…'}
 setStatus('جارٍ إرسال طلب التقديم…');
 try{
  const r=await sb.rpc('submit_job_application_backend',p);
  if(r.error){setStatus('تعذر إرسال الطلب بسبب الاتصال أو الصلاحيات. تحقق من البيانات ثم حاول مرة أخرى.',true);return}
  setStatus('تم إرسال التقديم بنجاح.');
  await load(defs['الوظائف']);tab='overview';render();
 }catch{
  setStatus('تعذر تأكيد إرسال التقديم. راجع حالة الطلب قبل إعادة المحاولة.',true);
 }finally{if(submit){submit.disabled=false;submit.textContent='إرسال التقديم'}}
}
function render(){const page=document.getElementById('page');if(!page||!current)return;const d=defs[current];if(loading){page.innerHTML=shell(d,tabs(d)+'<p class="muted">جاري تحميل البيانات الفعلية…</p>');return}if(error){page.innerHTML=shell(d,tabs(d)+'<div class="empty-state" role="alert">'+esc(error)+'</div>'+(error==='AUTH_REQUIRED'?'':'<button type="button" class="btn btn-outline" data-op-reload>إعادة تحميل البيانات</button>'));bind();return}page.innerHTML=tab==='overview'?overview(d):body(d);if(tab!=='overview'&&Object.keys(loadErrors).length&&!page.querySelector('[data-op-reload]')){const root=page.querySelector('.workspace-section');const retryMarkup=page.querySelector('[role="alert"]')?'<button type="button" class="btn btn-outline" data-op-reload>إعادة تحميل البيانات</button>':'<div class="notice" role="alert">تعذر تحميل بعض البيانات في هذه الصفحة. لم نعتبرها فارغة؛ يمكنك إعادة المحاولة.</div><button type="button" class="btn btn-outline" data-op-reload>إعادة تحميل البيانات</button>';root?.insertAdjacentHTML('beforeend',retryMarkup)}bind()}
function bindLivePagination(root=document){root.querySelectorAll('[data-live-page]').forEach(b=>{if(b.dataset.liveBound==='true')return;b.dataset.liveBound='true';b.addEventListener('click',()=>{if(b.disabled)return;const t=b.dataset.liveTable,input=document.querySelector('[data-live-search="'+CSS.escape(t)+'"]'),target=[...document.querySelectorAll('[data-live-results]')].find(el=>el.dataset.liveResults===t);if(target){target.innerHTML=genericLiveTable(t,input?.value||'',Number(b.dataset.livePage));bindLivePagination(target)}})})}
function bind(){document.querySelector('[data-op-reload]')?.addEventListener('click',()=>{if(current&&defs[current])load(defs[current])});document.querySelectorAll('[data-op-tab]').forEach(b=>b.onclick=async()=>{tab=b.dataset.opTab;if(current==='MantiGO والنقل'&&tab==='open'){const r=await sb.rpc('list_open_mantigo_rides_backend',{p_user_id:user.id});if(r.error){rows.mantigo_open=[];loadErrors.mantigo_open=r.error}else{delete loadErrors.mantigo_open;rows.mantigo_open=r.data||[]}}render()});document.querySelectorAll('[data-mg-vehicle]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-mg-vehicle]').forEach(x=>x.classList.remove('active'));b.classList.add('active');const v=document.getElementById('mgVehicle');if(v)v.value=b.dataset.mgVehicle});document.querySelector('[data-mg-location]')?.addEventListener('click',async()=>{const b=document.querySelector('[data-mg-location]');if(!navigator.geolocation)return alert('المتصفح لا يدعم تحديد الموقع.');b.disabled=true;b.textContent='جاري تحديد الموقع…';const p=await mgGetCurrentPosition();b.disabled=false;b.textContent='⌖ موقعي';if(!p)return alert('تعذر تحديد موقعك. اسمح للموقع من إعدادات المتصفح أو اكتب نقطة الانطلاق يدويًا.');const input=document.getElementById('mgPickup');if(input){input.value='موقعي الحالي';input.dataset.lat=p.lat;input.dataset.lon=p.lon}});document.getElementById('save-lead')?.addEventListener('click',saveLead);document.getElementById('mlSearch')?.addEventListener('input',e=>{const target=document.getElementById('mlLeadResults');if(target)target.innerHTML=marketingLeadTable(e.target.value)});document.querySelectorAll('[data-live-search]').forEach(input=>input.addEventListener('input',()=>{const t=input.dataset.liveSearch;const target=[...document.querySelectorAll('[data-live-results]')].find(el=>el.dataset.liveResults===t);if(target){target.innerHTML=genericLiveTable(t,input.value);bindLivePagination(target)}}));bindLivePagination(document);document.querySelectorAll('[data-job-apply]').forEach(b=>b.onclick=()=>{const form=document.querySelector('[data-job-form="'+CSS.escape(b.dataset.jobApply)+'"]');if(!form)return;const opening=form.hidden;form.hidden=!opening;b.setAttribute('aria-expanded',String(opening));if(opening)form.querySelector('textarea')?.focus()});document.querySelectorAll('[data-job-form]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();applyJob(form.dataset.jobForm,form)}));document.querySelectorAll('[data-edu-request]').forEach(b=>b.onclick=()=>{const form=document.querySelector('[data-edu-form="'+CSS.escape(b.dataset.eduRequest)+'"][data-edu-type="'+CSS.escape(b.dataset.eduType)+'"]');if(!form)return;const opening=form.hidden;form.hidden=!opening;b.setAttribute('aria-expanded',String(opening));if(opening)form.querySelector('input')?.focus()});document.querySelectorAll('[data-edu-form]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();createEducationRequest(form.dataset.eduForm,form.dataset.eduType,form)}));document.querySelectorAll('[data-medical-book]').forEach(b=>b.onclick=()=>{const form=document.querySelector('[data-medical-form="'+CSS.escape(b.dataset.medicalBook)+'"]');if(!form)return;const opening=form.hidden;form.hidden=!opening;b.setAttribute('aria-expanded',String(opening));if(opening)form.querySelector('input')?.focus()});document.querySelectorAll('[data-medical-form]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();medicalBook(form.dataset.medicalForm,form)}));document.getElementById('mgCreateRide')?.addEventListener('click',mgCreateRide);document.getElementById('mgSubmitBid')?.addEventListener('click',mgSubmitBid);document.querySelectorAll('[data-mg-bid]').forEach(b=>b.onclick=()=>{const id=b.dataset.mgBid,existing=document.querySelector('[data-mg-bid-form]');if(existing){if(existing.dataset.mgBidForm===id){existing.querySelector('input:not([type=hidden])')?.focus();return}existing.remove()}const box=b.closest('.card');if(!box)return;box.insertAdjacentHTML('beforeend',mantigoBidForm(id));box.querySelector('[data-mg-bid-form] input:not([type=hidden])')?.focus();bind()});document.querySelectorAll('[data-mg-accept]').forEach(b=>b.onclick=()=>mgAccept(b.dataset.mgAccept,b.dataset.mgRide));document.querySelectorAll('[data-mg-rate]').forEach(b=>b.onclick=()=>mgRate(b.dataset.mgRate));document.querySelectorAll('[data-mg-cancel]').forEach(b=>b.onclick=()=>mgTransition(b.dataset.mgCancel,'CANCELLED'));document.querySelectorAll('[data-mg-status]').forEach(b=>b.onclick=()=>mgTransition(b.dataset.mgRide,b.dataset.mgStatus));document.querySelectorAll('[data-mg-presence]').forEach(b=>b.onclick=()=>mgSetPresence(b.dataset.mgPresence));document.getElementById('mgApplyCaptain')?.addEventListener('click',mgApplyCaptain);document.querySelectorAll('[data-mg-cash-pay]').forEach(b=>b.onclick=()=>mgCashPay(b.dataset.mgCashPay));document.querySelectorAll('[data-mg-card-pay]').forEach(b=>b.onclick=()=>mgCardPay(b.dataset.mgCardPay))}
function observe(){const n=document.querySelector('.breadcrumb')?.textContent?.trim()||'';const d=defs[n];if(d&&!current){current=n;tab=d.key==='MANTIGO'?'request':'overview';load(d)}if(!d)current=null}new MutationObserver(observe).observe(document.body,{childList:true,subtree:true});setInterval(observe,800);
